#include <iostream>
#include <cstring>
using namespace std;

class DynamicString {
private:
    char* data;
    size_t length;

public:
    DynamicString() : data(nullptr), length(0) {
        data = new char[1];
        data[0] = '\0';
        length = 0;
    }

    DynamicString(const char* str) {
        if (str == nullptr) {
            data = new char[1];
            data[0] = '\0';
            length = 0;
        } else {
            length = strlen(str);
            data = new char[length + 1];
            strcpy(data, str);
        }
    }

    DynamicString(const DynamicString& other) {
        length = other.length;
        data = new char[length + 1];
        strcpy(data, other.data);
    }

    ~DynamicString() {
        delete[] data;
    }

    DynamicString& operator=(const DynamicString& other) {
        if (this == &other) {
            return *this;
        }

        delete[] data;

        length = other.length;
        data = new char[length + 1];
        strcpy(data, other.data);

        return *this;
    }

    DynamicString& operator=(const char* str) {
        if (str == nullptr) {
            delete[] data;
            data = new char[1];
            data[0] = '\0';
            length = 0;
            return *this;
        }

        if (data != nullptr) {
            delete[] data;
        }

        length = strlen(str);
        data = new char[length + 1];
        strcpy(data, str);

        return *this;
    }

    friend ostream& operator<<(ostream& os, const DynamicString& ds) {
        os << ds.data;
        return os;
    }
};

int main() {
    string line1, line2;
    getline(cin, line1);
    getline(cin, line2);

    DynamicString ds;
    ds = line2.c_str();

    cout << "After Assignment: " << ds << endl;

